4.4 Fijar la arquitectura antes de intervenir
Usaremos cinco capas ocultas de 128 unidades. Es deliberadamente más profunda y grande que la MLP del capítulo anterior: tiene capacidad suficiente para hacer visibles problemas de propagación y sobreajuste, pero sigue entrenando en CPU en segundos.

class DiagnosticMLP(nn.Module):
    def __init__(self, activation="relu", dropout=0.0, width=128, depth=5):
        super().__init__()
        self.activation_name = activation
        self.hidden_layers = nn.ModuleList()
        input_width = 16
        for _ in range(depth):
            self.hidden_layers.append(nn.Linear(input_width, width))
            input_width = width
        self.output = nn.Linear(input_width, 7)
        self.dropout = nn.Dropout(dropout)

    def activate(self, values):
        if self.activation_name == "sigmoid":
            return torch.sigmoid(values)
        return torch.relu(values)

    def forward(self, X):
        hidden = X
        for layer in self.hidden_layers:
            hidden = self.dropout(self.activate(layer(hidden)))
        return self.output(hidden)


